sql_gerado:
SELECT regiao, COUNT(*) AS quantidade
FROM estados
GROUP BY regiao;

SELECT COUNT(DISTINCT cliente_id) AS clientes_2024_2025
FROM pedidos
WHERE strftime('%Y', data_pedido) IN ('2024', '2025');

SELECT sigla FROM estados WHERE id IN (
    SELECT cliente_id FROM clientes GROUP BY cliente_id HAVING COUNT(*) < 4
)
